import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Session } from '../../core/session';
import { Dated } from './dated';

/** The roles a user name can have on a sheet; any name without one is a clerk. */
export const ROLES = ['clerk', 'steward', 'viewer'] as const;
export type Role = (typeof ROLES)[number];

export interface RoleGiven {
  user: string;
  role: Role;
}

/** The keys of the settings that carry a figure, each dated. */
export const DATED_KEYS = ['clerk-limit', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'cap', 'proof-threshold'] as const;
export type DatedKey = (typeof DATED_KEYS)[number];

/** The actions of the permission matrix, in the order they are shown. */
export const PERMISSIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;
export type Permission = (typeof PERMISSIONS)[number];

/** The settings in force on the sheet's today; `dated` has, for each setting that carries a figure, every value
 * recorded for it by from-date. */
export interface Settings {
  /** The highest due a clerk may settle, with two decimals; null for no limit. */
  clerkLimit: string | null;
  /** The least a claim's live due comes to, with two decimals. */
  floor: string;
  /** The days after its date a claim is due by. */
  terms: number;
  /** Each grade's own terms in days; null when the grade uses the sheet's terms. */
  termsA: number | null;
  termsB: number | null;
  termsC: number | null;
  /** What an overdue claim gains of its figure for every full 30 days overdue, with two decimals. */
  latePct: string;
  /** The date (yyyy-mm-dd) a claim dated before rounds half up, on or after half to even; null for the
   * sheet's today. */
  policyDate: string | null;
  /** The date (yyyy-mm-dd) from which, while the sheet's today is on or after it, a claim opened is numbered
   * within its period; null when off. */
  periodNumberingFrom: string | null;
  /** The most a person's due-total comes to, with two decimals; null for none. */
  cap: string | null;
  /** The due above which a claim needs a proof before it is settled or approved, with two decimals; null for
   * none. */
  proofThreshold: string | null;
  /** The days after a period's to-date it is closed when the sheet's today is changed past them; null when
   * off. */
  graceDays: number | null;
  dated: Record<DatedKey, Dated[]>;
  /** By action, the roles that may take it, comma separated; blank keeps the standing rule. */
  permissions: Record<Permission, string>;
}

// A sheet's settings: the role each user name has, its clerk limit, its floor, its terms and each grade's, its late percent, its policy date, its period numbering date, its cap, its proof threshold (those that carry a figure dated), its grace days and its permission matrix, read and changed through the
// server.
@Injectable({ providedIn: 'root' })
export class SettingsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  roles(sheetId: string): Observable<RoleGiven[]> {
    return this.http.get<RoleGiven[]>(`${this.url(sheetId)}/roles`, { headers: this.headers() });
  }

  setRole(sheetId: string, user: string, role: string): Observable<RoleGiven> {
    return this.http.put<RoleGiven>(`${this.url(sheetId)}/roles`, { user, role }, { headers: this.headers() });
  }

  get(sheetId: string): Observable<Settings> {
    return this.http.get<Settings>(`${this.url(sheetId)}/settings`, { headers: this.headers() });
  }

  /** Save the settings given; one left out is left as it is. A setting that carries a figure is recorded from
   * its from-date (`floorFrom` and so on), or from the sheet's today when none is given. */
  save(
    sheetId: string,
    settings: { clerkLimit?: string; floor?: string; terms?: string; termsA?: string; termsB?: string;
      termsC?: string; latePct?: string; policyDate?: string; periodNumberingFrom?: string; cap?: string;
      proofThreshold?: string; graceDays?: string; clerkLimitFrom?: string; floorFrom?: string; termsFrom?: string; termsAFrom?: string; termsBFrom?: string;
      termsCFrom?: string; latePctFrom?: string; capFrom?: string; proofThresholdFrom?: string;
      permOpen?: string; permSettle?: string; permVoid?: string; permReassign?: string; permClose?: string;
      permReopen?: string; },
  ): Observable<Settings> {
    return this.http.put<Settings>(`${this.url(sheetId)}/settings`, settings, { headers: this.headers() });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}
import { Component, DestroyRef, computed, inject, signal } from '@angular/core';
import { toObservable } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Subject, catchError, concatMap, forkJoin, map, of, switchMap } from 'rxjs';
import { Session } from '../../core/session';
import { DATED_KEYS, DatedKey, PERMISSIONS, Permission, ROLES, RoleGiven, Settings as SheetSettings, SettingsApi } from './settings-api';
import { valueOn } from './dated';
import { DEFAULT_FLOOR, SheetFloor } from './sheet-floor';
import { DEFAULT_LATE_PCT, SheetLatePct } from './sheet-late-pct';
import { SheetCap } from './sheet-cap';
import { SheetPolicyDate } from './sheet-policy-date';

/** The terms a sheet starts with, in days. */
const DEFAULT_TERMS = 14;
/** The grades that can have terms of their own. */
const GRADES = ['A', 'B', 'C'] as const;
type GradeTermsKey = `terms${(typeof GRADES)[number]}`;
/** The settings in the form that carry a figure, each saved from a from-date, by the key the sheet keeps them by. */
const DATED_FIELDS = {
  clerkLimit: 'clerk-limit',
  floor: 'floor',
  terms: 'terms',
  termsA: 'terms-A',
  termsB: 'terms-B',
  termsC: 'terms-C',
  latePct: 'late-pct',
  cap: 'cap',
  proofThreshold: 'proof-threshold',
} as const satisfies Record<string, DatedKey>;
type DatedField = keyof typeof DATED_FIELDS;
type FromField = `${DatedField}From`;
/** The setting holding each action's roles in the form. */
const PERMISSION_FIELDS = {
  open: 'permOpen',
  settle: 'permSettle',
  void: 'permVoid',
  reassign: 'permReassign',
  close: 'permClose',
  reopen: 'permReopen',
} as const satisfies Record<Permission, string>;
type PermissionField = (typeof PERMISSION_FIELDS)[Permission];
const LIMIT = /^\d{1,10}(\.\d{1,2})?$/;
const DAYS = /^\d{1,5}$/;
const PCT = /^\d{1,5}(\.\d{1,2})?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;
type SettingsFormValue = {
  clerkLimit: string;
  floor: string;
  terms: string;
  termsA: string;
  termsB: string;
  termsC: string;
  latePct: string;
  policyDate: string;
  periodNumberingFrom: string;
  cap: string;
  proofThreshold: string;
  graceDays: string;
} & Record<PermissionField, string>;

const NO_SETTINGS: SheetSettings = {
  clerkLimit: null,
  floor: DEFAULT_FLOOR,
  terms: DEFAULT_TERMS,
  termsA: null,
  termsB: null,
  termsC: null,
  latePct: DEFAULT_LATE_PCT,
  policyDate: null,
  periodNumberingFrom: null,
  cap: null,
  proofThreshold: null,
  graceDays: null,
  dated: Object.fromEntries(DATED_KEYS.map((k) => [k, []])) as unknown as SheetSettings['dated'],
  permissions: Object.fromEntries(PERMISSIONS.map((p) => [p, ''])) as Record<Permission, string>,
};

// The sheet's settings: the role each user name has (clerk unless given another) with the form that
// gives one, the clerk limit, the highest due a clerk may settle (blank for no limit), and the floor, the
// least a claim's live due comes to, the terms, the days after its date a claim is due by (fixed when it is
          formControlName="periodNumberingFrom"
        />
        <label for="setting-cap">Cap (blank for none)</label>
        <input id="setting-cap" data-testid="setting-cap" inputmode="decimal" formControlName="cap" />
        <label for="setting-cap-from">Cap from (yyyy-mm-dd, blank for the sheet's today)</label>
        <input id="setting-cap-from" data-testid="setting-cap-from" formControlName="capFrom" />
        <label for="setting-proof-threshold">Proof threshold (blank for none)</label>
        <input
          id="setting-proof-threshold"
          data-testid="setting-proof-threshold"
          inputmode="decimal"
          formControlName="proofThreshold"
        />
        <label for="setting-proof-threshold-from">Proof threshold from (yyyy-mm-dd, blank for the sheet's today)</label>
        <input
          id="setting-proof-threshold-from"
          data-testid="setting-proof-threshold-from"
          formControlName="proofThresholdFrom"
        />
        <label for="setting-grace-days">Grace days (blank for off)</label>
        <input id="setting-grace-days" data-testid="setting-grace-days" inputmode="numeric" formControlName="graceDays" />
        @for (p of permissions; track p) {
          <label [for]="'setting-perm-' + p">Roles that may {{ p }} (comma separated, blank for the standing rule)</label>
          <input [id]="'setting-perm-' + p" [attr.data-testid]="'setting-perm-' + p" [formControlName]="permissionField(p)" />
        }
        <button type="submit" data-testid="settings-save">Save settings</button>
      </form>
      @if (settingsError(); as e) {
        <p role="alert" data-testid="settings-error">{{ e }}</p>
      }
      <p>
        Clerk limit in force:
        <span data-testid="setting-clerk-limit-current">{{ inForce().clerkLimit ?? '' }}</span>
      </p>
      <p>
        Floor in force:
        <span data-testid="setting-floor-current">{{ inForce().floor }}</span>
      </p>
      <p>
